SQL_DOC.P_SQL:
DECLARE
V_COUNT NUMBER;
BEGIN
V_COUNT := 0;
SELECT COUNT(*) INTO V_COUNT FROM UCUBE.XOIF_PUR_KEP_REQ WHERE 1=1 AND INTERFACE_HEADER_ID = $INTERFACE_HEADER_ID$ AND LINE_NUM = $LINE_NUM$ ;
IF V_COUNT=0 THEN
INSERT INTO UCUBE.XOIF_PUR_KEP_REQ( INTERFACE_HEADER_ID , ATTRIBUTE1 , ATTRIBUTE2 , ATTRIBUTE3 , ATTRIBUTE4 , ATTRIBUTE5 , ATTRIBUTE6 , ATTRIBUTE7 , ATTRIBUTE8 , ATTRIBUTE9 , ATTRIBUTE10 , LAST_UPDATE_DATE , LAST_UPDATED_BY , CREATION_DATE , CREATED_BY , LAST_UPDATE_LOGIN , CURRENCY_CODE , APPROVAL_STATUS , COMMENTS , LINE_NUM , ITEM , CATEGORY_ID , UNIT_PRICE , ORIGINAL_SOURCING_SITE )VALUES( $INTERFACE_HEADER_ID$ , $ATTRIBUTE1$ , $ATTRIBUTE2$ , $ATTRIBUTE3$ , $ATTRIBUTE4$ , $ATTRIBUTE5$ , $ATTRIBUTE6$ , $ATTRIBUTE7$ , $ATTRIBUTE8$ , $ATTRIBUTE9$ , $ATTRIBUTE10$ , $LAST_UPDATE_DATE$ , $LAST_UPDATED_BY$ , $CREATION_DATE$ , $CREATED_BY$ , $LAST_UPDATE_LOGIN$ , $CURRENCY_CODE$ , $APPROVAL_STATUS$ , $COMMENTS$ , $LINE_NUM$ , $ITEM$ , $CATEGORY_ID$ , $UNIT_PRICE$ , $ORIGINAL_SOURCING_SITE$ );
ELSE
UPDATE UCUBE.XOIF_PUR_KEP_REQ SET INTERFACE_HEADER_ID = $INTERFACE_HEADER_ID$ , ATTRIBUTE1 = $ATTRIBUTE1$ , ATTRIBUTE2 = $ATTRIBUTE2$ , ATTRIBUTE3 = $ATTRIBUTE3$ , ATTRIBUTE4 = $ATTRIBUTE4$ , ATTRIBUTE5 = $ATTRIBUTE5$ , ATTRIBUTE6 = $ATTRIBUTE6$ , ATTRIBUTE7 = $ATTRIBUTE7$ , ATTRIBUTE8 = $ATTRIBUTE8$ , ATTRIBUTE9 = $ATTRIBUTE9$ , ATTRIBUTE10 = $ATTRIBUTE10$ , LAST_UPDATE_DATE = $LAST_UPDATE_DATE$ , LAST_UPDATED_BY = $LAST_UPDATED_BY$ , CREATION_DATE = $CREATION_DATE$ , CREATED_BY = $CREATED_BY$ , LAST_UPDATE_LOGIN = $LAST_UPDATE_LOGIN$ , CURRENCY_CODE = $CURRENCY_CODE$ , APPROVAL_STATUS = $APPROVAL_STATUS$ , COMMENTS = $COMMENTS$ , LINE_NUM = $LINE_NUM$ , ITEM = $ITEM$ , CATEGORY_ID = $CATEGORY_ID$ , UNIT_PRICE = $UNIT_PRICE$ , ORIGINAL_SOURCING_SITE = $ORIGINAL_SOURCING_SITE$ WHERE 1=1 AND INTERFACE_HEADER_ID = $INTERFACE_HEADER_ID$ AND LINE_NUM = $LINE_NUM$ ;
END IF;
END;
